function openAseanDrawer(code){const member=ASEAN_MEMBERS.find(m=>m.code===code);if(!member)return;const r=regionalData();const claims=r.asean.filter(v=>v._member?.code===code).sort((a,b)=>dateMs(b.discovered)-dateMs(a.discovered));const d30=claims.filter(v=>withinDays(v.discovered,30)).length,d90=claims.filter(v=>withinDays(v.discovered,90)).length,groups=countBy(claims,v=>v.group||'Unknown'),sectors=countBy(claims,v=>v.sector||'Unspecified'),src=ransomwareCountryUrl(code);const rows=claims.slice(0,60).map(v=>`<div class="country-claim"><div><strong>${esc(v.victim||'Unknown victim')}</strong><small>${esc(v.group||'Unknown group')} · ${esc(v.sector||'Unspecified sector')}</small></div><time>${esc(v.discovered?fmtDate(v.discovered):'Unknown date')}</time></div>`).join('')||'<div class="empty-state">No retained claims for this country yet. The rolling archive begins from the time this patch is installed.</div>';$('drawerContent').innerHTML=`<span class="drawer-kicker">ASEAN RANSOMWARE INTELLIGENCE</span><h2 class="drawer-title">${member.flag} ${esc(member.name)}</h2><p class="drawer-sub">Public ransomware/extortion victim claims · rolling retained history</p><div class="drawer-score-grid"><div><span>Retained claims</span><strong>${fmt(claims.length)}</strong></div><div><span>≤30 days</span><strong>${fmt(d30)}</strong></div><div><span>≤90 days</span><strong>${fmt(d90)}</strong></div></div><div class="drawer-section drawer-meta"><h4>Regional profile</h4><div><span>Top ransomware group</span><strong>${esc(groups[0]?.name||'—')}</strong></div><div><span>Top targeted sector</span><strong>${esc(sectors[0]?.name||'—')}</strong></div><div><span>History source</span><strong>${sourceReady(RWHIST)?'Rolling archive':'Latest 100 feed'}</strong></div></div><div class="drawer-section"><h4>Retained victim claims</h4><div class="country-claim-list">${rows}</div></div><div class="drawer-links"><a href="${esc(src)}" target="_blank" rel="noopener">Open ransomware.live country view ↗</a><a href="${esc(ransomwareSourceUrl())}" target="_blank" rel="noopener">Open source platform ↗</a></div><div class="drawer-note">Claims are OSINT disclosures from ransomware/extortion leak sites and are not independently verified incidents. The Phase 1 rolling archive accumulates new records from the public recent-victims feed over time.</div>`;$('detailDrawer').classList.add('open');$('drawerBackdrop').classList.add('open');$('detailDrawer').setAttribute('aria-hidden','false')}
function openCveDrawer(id){const v=UNIFIED.find(x=>x.id===id);if(!v)return;const cv=v.nvd?.cvss||{},epss=v.epss?`${(safeNum(v.epss.epss)*100).toFixed(2)}%`:'—',events=[];const push=(date,title,text,tone='cyan')=>{if(date&&dateMs(date))events.push({date,title,text,tone,ms:dateMs(date)})};push(v.nvd?.published||v.nvd?.publishedAt,'NVD published','Initial vulnerability record','blue');push(v.dateAdded,'Added to CISA KEV','Known exploitation confirmed by CISA','red');push(EPSS?.meta?.scoreDate,'FIRST EPSS score',v.epss?`${(safeNum(v.epss.epss)*100).toFixed(2)}% exploitation probability`:'No matched EPSS score','amber');push(v.nvd?.lastModified,'NVD last modified','Latest NVD metadata update','cyan');push(v.dueDate,'CISA remediation due','Required-action due date','green');events.sort((a,b)=>a.ms-b.ms);const timeline=events.length?events.map(e=>`<div class="evidence-event ${e.tone}"><i></i><div><time>${esc(new Date(e.ms).toLocaleDateString())}</time><strong>${esc(e.title)}</strong><span>${esc(e.text)}</span></div></div>`).join(''):'<div class="empty-state">Timeline metadata not available.</div>',reasons=vulnWhy(v),bd=v.priority.breakdown||{},refs=(v.nvd?.references||[]).filter(r=>safeHttpUrl(r.url)!=='#').slice(0,5),refLinks=refs.map(r=>`<a href="${esc(safeHttpUrl(r.url))}" target="_blank" rel="noopener">${esc((r.tags||[])[0]||'Reference')} ↗</a>`).join('');$('drawerContent').innerHTML=`<span class="drawer-kicker">VULNERABILITY INTELLIGENCE 2.0 · CORRELATED EVIDENCE</span><div class="drawer-title-row"><div><h2 class="drawer-title">${esc(v.id)}</h2><p class="drawer-sub">${esc(v.vendor)} · ${esc(v.product)}</p></div><span class="priority p-${v.priority.label.toLowerCase()}">${v.priority.label} · THREADHUB ${v.priority.score}/100</span></div><div class="drawer-score-grid four"><div><span>CVSS</span><strong>${cv.score==null?'—':safeNum(cv.score).toFixed(1)}</strong><small>${esc(cv.severity||'UNKNOWN')}</small></div><div><span>EPSS</span><strong>${epss}</strong><small>${v.epss?`${(safeNum(v.epss.percentile)*100).toFixed(1)} percentile`:'No score'}</small></div><div><span>CISA KEV</span><strong class="text-red">YES</strong><small>Exploitation confirmed</small></div><div><span>Ransomware</span><strong class="${v.ransomware?'text-red':'text-green'}">${v.ransomware?'KNOWN':'NOT KNOWN'}</strong><small>Campaign use</small></div></div><div class="drawer-section why-matters-section"><h4>Why this matters</h4><div class="why-matters-list">${reasons.map((r,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><p>${esc(r)}</p></div>`).join('')}</div></div><div class="drawer-section signal-meter-section"><div class="signal-meter-head"><h4>ThreadHub priority signal</h4><strong>${v.priority.score}/100</strong></div><div class="signal-meter"><i style="width:${v.priority.score}%"></i></div><div class="priority-breakdown"><div><span>CVSS severity</span><strong>+${safeNum(bd.severity)}</strong></div><div><span>EPSS probability</span><strong>+${safeNum(bd.epss)}</strong></div><div><span>Ransomware use</span><strong>+${safeNum(bd.ransomware)}</strong></div><div><span>KEV recency</span><strong>+${safeNum(bd.recency)}</strong></div></div><p>This is an external-intelligence prioritisation signal, not an organisational risk score.</p></div><div class="drawer-section correlation-section"><h4>Correlation status</h4><div class="correlation-chain"><span>CISA KEV <b>KNOWN EXPLOITED</b></span><i>→</i><span>NVD <b>${esc(cv.severity||'UNSCORED')}</b></span><i>→</i><span>EPSS <b>${epss}</b></span><i>→</i><span>Ransomware <b>${v.ransomware?'KNOWN USE':'NO KNOWN USE'}</b></span></div><p>${v.ransomware?'CISA identifies known ransomware campaign use. The current ThreadHub source set does not attribute that use to a specific ransomware group, so no actor relationship is inferred.':'No ransomware use is currently identified by the loaded CISA KEV record. ThreadHub does not infer a ransomware-group relationship without source evidence.'}</p></div><div class="drawer-section"><h4>Vulnerability</h4><p>${esc(v.vulnerabilityName||v.nvd?.description||v.description||'No description available.')}</p></div><div class="drawer-section"><h4>NVD description</h4><p>${esc(v.nvd?.description||'No NVD description available.')}</p></div><div class="drawer-section action-section"><h4>CISA required action</h4><p>${esc(v.requiredAction||'No action text available.')}</p></div><div class="drawer-section"><h4>Evidence timeline</h4><div class="evidence-timeline">${timeline}</div></div><div class="drawer-section drawer-meta"><h4>Technical evidence</h4><div><span>Date added to KEV</span><strong>${esc(v.dateAdded||'—')}</strong></div><div><span>CISA due date</span><strong>${esc(v.dueDate||'—')}</strong></div><div><span>CVSS vector</span><strong>${esc(cv.vector||'—')}</strong></div><div><span>CWE</span><strong>${esc((v.nvd?.cwes||v.cwes||[]).join(', ')||'—')}</strong></div><div><span>EPSS percentile</span><strong>${v.epss?`${(safeNum(v.epss.percentile)*100).toFixed(1)}%`:'—'}</strong></div><div><span>NVD last modified</span><strong>${esc(v.nvd?.lastModified?fmtDate(v.nvd.lastModified):'—')}</strong></div></div><div class="drawer-section"><h4>Source traceability</h4><div class="drawer-links evidence-source-links"><a href="${esc(nvdUrl(v.id))}" target="_blank" rel="noopener">NVD record ↗</a><a href="${esc(cisaCveUrl(v.id))}" target="_blank" rel="noopener">CISA KEV ↗</a><a href="${esc(epssUrl(v.id))}" target="_blank" rel="noopener">FIRST EPSS ↗</a>${refLinks}</div></div><div class="drawer-note">ThreadHub separates source-backed facts from inference. KEV status, CVSS, EPSS and CISA ransomware-use flags are shown from their respective sources; actor attribution is not created unless the source data supports it.</div>`;$('detailDrawer').classList.add('open');$('drawerBackdrop').classList.add('open');$('detailDrawer').setAttribute('aria-hidden','false')}
function closeDrawer(){$('detailDrawer').classList.remove('open');$('drawerBackdrop').classList.remove('open');$('detailDrawer').setAttribute('aria-hidden','true')}

function renderBriefing(){const p=posture(),reg=regionalData(),events=buildEvents(),sources=sourceStates(),top=topKevs(5),healthy=sources.filter(x=>x.ready&&!x.degraded).length,degraded=sources.filter(x=>x.degraded).length,offline=sources.filter(x=>!x.ready).length,confidence=offline>=2?'LIMITED':degraded||offline?'MODERATE':'HIGH',latest=events[0],topGroup=(RW?.topGroups||[])[0]||reg.topGroup,latestMy=MYCERT?.advisories?.[0];$('briefHeadline').textContent=`${p.label} external threat posture · ${fmt(p.critical)} critical-priority KEVs`;$('briefGeneratedAt').textContent=`Generated ${new Date().toLocaleString()}`;$('briefWindow').textContent=latest?`Latest signal: ${eventTime(latest)}`:'Current window';$('briefConfidence').textContent=`Confidence ${confidence}`;$('briefSummary').textContent=`Current external intelligence shows ${fmt(p.critical)} known exploited vulnerabilities at Critical CTI priority. ${fmt(p.epssHigh)} KEVs have EPSS ≥50%, while the loaded ransomware feed contains ${fmt(p.rw24)} claims discovered within 24 hours. Malaysia has ${fmt(reg.malaysia.filter(v=>withinDays(v.discovered,30)).length)} loaded claims within 30 days.`;const pri=[{tone:'critical',n:'01',t:'Exploit-priority vulnerabilities',v:fmt(p.critical),txt:top[0]?`${top[0].id} leads the watchlist at ${top[0].priority.score}/100${top[0].ransomware?', with known ransomware use':''}.`:'Waiting for correlated KEV intelligence.'},{tone:'ransomware',n:'02',t:'Ransomware activity',v:fmt(p.rw24),txt:topGroup?`${topGroup.name||'Unknown'} is the leading group in the currently loaded ranking.`:'Waiting for ransomware intelligence.'},{tone:'regional',n:'03',t:'Malaysia / ASEAN watch',v:fmt(reg.malaysia.filter(v=>withinDays(v.discovered,30)).length),txt:latestMy?`Latest MyCERT signal: ${latestMy.title}.`:'MyCERT collection pending.'}];$('briefPriorities').innerHTML=pri.map(x=>`<div class="brief-priority"><span class="brief-num">${x.n}</span><div><span>${esc(x.t)}</span><strong>${esc(x.v)}</strong><p>${esc(x.txt)}</p></div></div>`).join('');$('briefChanges').innerHTML=events.slice(0,5).map(e=>`<div class="brief-list-item"><i class="brief-dot sev-${e.severity}"></i><div><strong>${esc(e.title)}</strong><small>${esc(e.source)} · ${esc(eventTime(e))}</small></div></div>`).join('');const watch=[];if(top[0])watch.push(`${top[0].id}: CTI ${top[0].priority.score}/100${top[0].epss?`, EPSS ${(safeNum(top[0].epss.epss)*100).toFixed(1)}%`:''}.`);if(topGroup)watch.push(`Monitor ${topGroup.name||'leading ransomware group'} activity and changes in country/sector targeting.`);if(latestMy)watch.push(`Review MyCERT: ${latestMy.title}.`);if(degraded)watch.push(`Collection assurance: ${sources.filter(x=>x.degraded).map(x=>x.name).join(', ')} is degraded; last good data is retained.`);else if(offline)watch.push(`Restore unavailable source: ${sources.filter(x=>!x.ready).map(x=>x.name).join(', ')}.`);else watch.push('All collection sources are healthy; continue automated monitoring.');$('briefWatch').innerHTML=watch.map((x,i)=>`<div class="brief-list-item"><span class="brief-num">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(x)}</strong></div></div>`).join('');$('executiveWatchlist').innerHTML=top.map((v,i)=>`<div class="watchlist-row" data-cve="${esc(v.id)}"><span class="watch-rank">${String(i+1).padStart(2,'0')}</span><div class="watch-main"><div><strong>${esc(v.id)}</strong><span class="priority p-${v.priority.label.toLowerCase()}">${v.priority.label}</span></div><small>${esc(v.vendor)} · ${esc(v.product)}</small><div class="watch-metrics"><span>CTI <b>${v.priority.score}</b></span><span>CVSS <b>${v.nvd?.cvss?.score??'—'}</b></span><span>EPSS <b>${v.epss?`${(safeNum(v.epss.epss)*100).toFixed(1)}%`:'—'}</b></span>${v.ransomware?'<span class="rw-flag">RANSOMWARE</span>':''}</div></div></div>`).join('');$('regionalBrief').innerHTML=`<div class="regional-kpis"><div><span>Malaysia ≤30d</span><strong>${fmt(reg.malaysia.filter(v=>withinDays(v.discovered,30)).length)}</strong></div><div><span>ASEAN loaded</span><strong>${fmt(reg.asean.length)}</strong></div><div><span>ASEAN ≤24h</span><strong>${fmt(reg.asean.filter(v=>withinDays(v.discovered,1)).length)}</strong></div><div><span>Top country</span><strong>${esc(reg.topCountry?.count?reg.topCountry.member.name:'—')}</strong></div></div>`;$('briefSourceState').textContent=offline?`${healthy} healthy · ${offline} unavailable`:degraded?`${healthy} live · ${degraded} degraded`:`${healthy} / 5 healthy`;$('briefSourceHealth').innerHTML=sources.map(s=>`<div class="brief-source-row"><span class="brief-source-code">${esc(s.code)}</span><div><strong>${esc(s.name)}</strong><small>${esc(s.collected?relTime(s.collected):'Not collected')}</small></div><b class="brief-source-state ${!s.ready?'offline':s.degraded?'degraded':''}">${!s.ready?'OFFLINE':s.degraded?'DEGRADED':'LIVE'}</b></div>`).join('')}
function briefText(){const p=posture(),reg=regionalData(),sources=sourceStates(),top=topKevs(3),events=buildEvents().slice(0,4);return['CYBER THREAT INTELLIGENCE — EXECUTIVE BRIEF',`Generated: ${new Date().toLocaleString()}`,'',`Posture: ${p.label} (${p.score}/100)`,`Critical-priority KEVs: ${p.critical}`,`KEVs EPSS ≥50%: ${p.epssHigh}`,`Ransomware claims ≤24h: ${p.rw24}`,`Malaysia claims ≤30d: ${reg.malaysia.filter(v=>withinDays(v.discovered,30)).length}`,'','TOP WATCHLIST',...top.map((v,i)=>`${i+1}. ${v.id} — CTI ${v.priority.score}; CVSS ${v.nvd?.cvss?.score??'—'}; EPSS ${v.epss?`${(safeNum(v.epss.epss)*100).toFixed(1)}%`:'—'}; ransomware ${v.ransomware?'known':'not known'}`),'','LATEST SIGNALS',...events.map((e,i)=>`${i+1}. ${e.source}: ${e.title} (${eventTime(e)})`),'','SOURCE HEALTH',...sources.map(s=>`${s.name}: ${!s.ready?'OFFLINE':s.degraded?'DEGRADED':'LIVE'}`)].join('\n')}

function renderSources(){
  const core=sourceStates(),pulse=pulseSourceStates(),summary=allSourceSummary();
  if($('sourceActiveTotal'))$('sourceActiveTotal').textContent=fmt(summary.all.length);
  if($('sourceHealthyTotal'))$('sourceHealthyTotal').textContent=fmt(summary.healthy);
  if($('sourceFailedTotal'))$('sourceFailedTotal').textContent=fmt(summary.failed);
  if($('sourceClassTotal'))$('sourceClassTotal').textContent=fmt(PULSE_WEB?.meta?.sourceClasses||summary.classes);
  if($('sourceRegistryBadge'))$('sourceRegistryBadge').textContent=`WAVE 3 · ${fmt(PULSE_WEB?.meta?.sourcesConfigured||pulse.length)} PULSE SOURCES`;
  if($('pulseRegistrySummary'))$('pulseRegistrySummary').textContent=pulse.length?`${fmt(pulse.filter(x=>x.ready).length)} healthy of ${fmt(pulse.length)} configured · checked ${relTime(PULSE_WEB?.meta?.collectedAt)}`:'Run the Update ThreadHub Pulse workflow to populate Internet source health.';
  if($('pulseSourceTable'))$('pulseSourceTable').innerHTML=pulse.length?pulse.map(s=>{const auth=s.status==='auth-required',label=s.ready?'HEALTHY':auth?'AUTH REQUIRED':'FAILED',cls=s.ready?'ok':auth?'warn':'bad';return `<a class="pulse-source-row" href="${esc(safeHttpUrl(s.url))}" target="_blank" rel="noopener"><span class="source-health-dot ${cls}"></span><div class="pulse-source-name"><strong>${esc(s.name)}</strong><small>${esc(s.sourceClass)} · ${esc(String(s.collectorType).toUpperCase())}</small></div><span class="pulse-source-items">${fmt(s.items)}<small>items</small></span><span class="pulse-source-time">${esc(s.collected?relTime(s.collected):'—')}<small>${fmt(Math.round(s.durationMs))} ms</small></span><span class="pulse-source-status ${cls}">${label}</span><b>↗</b>${!s.ready&&s.error?`<em title="${esc(s.error)}">${esc(String(s.error).slice(0,70))}</em>`:''}</a>`}).join(''):'<div class="empty-state">No Pulse source-health records yet. Run the GitHub Action once.</div>';
  if($('sourceCards'))$('sourceCards').innerHTML=core.map(s=>`<article class="source-card"><span class="source-state ${!s.ready?'offline':s.degraded?'warn':''}">${!s.ready?'OFFLINE':s.degraded?'DEGRADED':'LIVE'}</span><span class="source-code">${esc(s.code)}</span><h3>${esc(s.name)}</h3><p>${esc(s.desc)}</p><div class="source-meta"><span>Collected: ${esc(s.collected?fmtDate(s.collected):'Not collected')}</span><span>Age: ${esc(s.collected?relTime(s.collected):'—')}</span></div><a href="${esc(s.url)}" target="_blank" rel="noopener">Open authoritative source ↗</a></article>`).join('');
}


/* Phase 1H.2 — Global ransomware map + explorer */
let COUNTRY_META=null,WORLD_SVG='',COUNTRY_ALIAS=new Map(),RW_WINDOW='1';
let RW_QUERY='',RW_GROUP_FILTER='all',RW_COUNTRY_FILTER='all',RW_SECTOR_FILTER='all',RW_CLAIM_PAGE=1;
const RW_CLAIM_PAGE_SIZE=25;
const countryAliasKey=v=>String(v||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').trim();
function initCountryAlias(){COUNTRY_ALIAS=new Map();for(const c of COUNTRY_META?.countries||[]){const vals=[c.name,c.alpha2,c.alpha3,...(c.aliases||[])];for(const a of vals){const k=countryAliasKey(a);if(k)COUNTRY_ALIAS.set(k,c)}}const extras={'usa':'United States','us':'United States','u s':'United States','united states of america':'United States','uk':'United Kingdom','u k':'United Kingdom','great britain':'United Kingdom','russia':'Russian Federation','viet nam':'Vietnam','south korea':'South Korea','republic of korea':'South Korea','korea south':'South Korea','north korea':'North Korea','czechia':'Czech Republic','lao pdr':'Laos','lao peoples democratic republic':'Laos','brunei darussalam':'Brunei','timor leste':'East Timor','east timor':'East Timor'};for(const[k,n]of Object.entries(extras)){const c=[...(COUNTRY_META?.countries||[])].find(x=>countryAliasKey(x.name)===countryAliasKey(n));if(c)COUNTRY_ALIAS.set(k,c)}}
function countryInfo(raw){const k=countryAliasKey(raw);if(!k)return null;return COUNTRY_ALIAS.get(k)||null}
function ransomwareBaseVictims(){const m=new Map();const put=v=>{if(!v)return;const key=String(v.id||`${v.victim||''}|${v.group||''}|${v.discovered||''}|${v.country||''}`);if(key)m.set(key,v)};if(sourceReady(RWHIST))for(const v of RWHIST.victims||[])put(v);if(sourceReady(RW))for(const v of RW.victims||[])put(v);return[...m.values()]}
function ransomwareVictimsSorted(){return ransomwareBaseVictims().slice().filter(v=>dateMs(v.discovered)).sort((a,b)=>dateMs(b.discovered)-dateMs(a.discovered))}
function ransomwareLiveVictims(){return ransomwareVictimsSorted().filter(v=>withinDays(v.discovered,1))}
function claimAgeHours(v){const t=dateMs(v?.discovered);return t?Math.max(0,(Date.now()-t)/3600000):Infinity}
function claimAgeClass(v){const h=claimAgeHours(v);return h<1?'now':h<6?'recent':h<=24?'day':'stale'}
function latestClaim(){return ransomwareVictimsSorted()[0]||null}
function renderRansomwareLivePulse(){const filteredAll=rwFilteredVictims(ransomwareBaseVictims()),live=filteredAll.filter(v=>withinDays(v.discovered,1)).sort((a,b)=>dateMs(b.discovered)-dateMs(a.discovered)),latest=live[0]||filteredAll.slice().filter(v=>dateMs(v.discovered)).sort((a,b)=>dateMs(b.discovered)-dateMs(a.discovered))[0]||null,countries=rwCountryRows(live).rows,groups=rwGroupRows(live),my=live.filter(v=>countryInfo(v.country)?.alpha2==='MY');if($('rwPulseLatest'))$('rwPulseLatest').textContent=latest?relTime(latest.discovered):'No matching claim';if($('rwPulseLatestMeta'))$('rwPulseLatestMeta').textContent=latest?`${latest.victim||'Unknown victim'} · ${latest.group||'Unknown group'} · ${countryInfo(latest.country)?.name||latest.country||'Unknown country'}`:'No claim matches the current investigation filters';if($('rwPulse24'))$('rwPulse24').textContent=fmt(live.length);if($('rwPulseCountries'))$('rwPulseCountries').textContent=fmt(countries.length);if($('rwPulseGroups'))$('rwPulseGroups').textContent=fmt(groups.length);if($('rwPulseMalaysia'))$('rwPulseMalaysia').textContent=fmt(my.length);renderMapLiveClaims(live,latest)}
function renderMapLiveClaims(live,latest){const list=live.length?live:(latest?[latest]:[]),host=$('rwMapLiveClaims');if(!host)return;host.innerHTML=list.slice(0,12).map((v,i)=>{const c=countryInfo(v.country),age=claimAgeClass(v),fallback=!live.length;return`<button class="rw-live-claim age-${age}" type="button" data-rw-claim="${esc(v.id||'')}"><span class="claim-age-dot"></span><div><strong>${esc(v.victim||'Unknown victim')}</strong><small>${esc(v.group||'Unknown group')} · ${esc(c?.name||v.country||'Unknown')}</small><em>${fallback?'Latest known claim · ':''}${esc(relTime(v.discovered))}</em></div><span class="rw-live-arrow">↗</span></button>`}).join('')||'<div class="empty-state">No timestamped ransomware claims available.</div>'}
function rwWindowDays(){return RW_WINDOW==='all'?null:safeNum(RW_WINDOW,90)}
