async function fetchJson(path){const r=await fetch(`${path}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`${path}: HTTP ${r.status}`);return r.json()}
async function fetchText(path){const r=await fetch(`${path}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`${path}: HTTP ${r.status}`);return r.text()}
async function refreshRansomwareFast({announce=true}={}){
  if(RW_FAST_POLLING)return;RW_FAST_POLLING=true;
  try{
    const next=await fetchJson('data/ransomware.json');
    if(!sourceReady(next))return;
    const nextIds=new Set((next.victims||[]).map(v=>String(v.id||'')).filter(Boolean));
    const previous=RW_SEEN_RECENT_IDS;
    RW_NEW_IDS=new Set();
    if(previous){for(const id of nextIds)if(!previous.has(id))RW_NEW_IDS.add(id)}
    const changed=(next?.meta?.collectedAt||'')!==(RW?.meta?.collectedAt||'')||RW_NEW_IDS.size>0;
    RW=next;RW_SEEN_RECENT_IDS=nextIds;
    if(changed){
      renderHeader();renderPosture();renderTopThree();renderRansomware();renderOverviewAsean();renderOverviewFeed();renderThreadHubOverview();renderStandaloneThreatMap();renderThreatActors();renderFeedStatusView();renderPulse();renderRegional();renderUnifiedFeed();renderBriefing();renderSources();
      if(announce&&RW_NEW_IDS.size){const latest=(next.victims||[]).filter(v=>RW_NEW_IDS.has(String(v.id||''))).sort((a,b)=>dateMs(b.discovered)-dateMs(a.discovered))[0];if(latest)toast(`New ransomware claim: ${latest.victim||'Unknown'} · ${latest.group||'Unknown group'}`)}
      const sync=document.getElementById('rwBrowserSync');if(sync){sync.textContent=`AUTO SYNC · ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;sync.classList.add('flash');setTimeout(()=>sync.classList.remove('flash'),900)}
      setTimeout(()=>{RW_NEW_IDS=new Set();renderRansomware()},4500);
    }else{const sync=document.getElementById('rwBrowserSync');if(sync)sync.textContent=`AUTO SYNC · checked ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;renderOverviewWorldMap();renderStandaloneThreatMap();renderOverviewFeed()}
  }catch(err){const sync=document.getElementById('rwBrowserSync');if(sync)sync.textContent='AUTO SYNC · retrying';console.warn('Ransomware fast poll failed',err)}finally{RW_FAST_POLLING=false;OVERVIEW_NEXT_RW_CHECK=Date.now()+60000;updateOverviewSyncLabel()}
}
function startRansomwareAutoSync(){
  clearInterval(RW_FAST_TIMER);clearInterval(OVERVIEW_SYNC_TIMER);OVERVIEW_NEXT_RW_CHECK=Date.now()+60000;updateOverviewSyncLabel();
  RW_FAST_TIMER=setInterval(()=>refreshRansomwareFast(),60*1000);OVERVIEW_SYNC_TIMER=setInterval(updateOverviewSyncLabel,1000);
  window.addEventListener('focus',()=>refreshRansomwareFast({announce:false}));
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshRansomwareFast({announce:false})});
}

async function load(){const paths=['data/kev.json','data/nvd.json','data/epss.json','data/ransomware.json','data/ransomware-history.json','data/mycert.json','data/country-meta.json','data/pulse.json'];const [res,mapRes]=await Promise.all([Promise.allSettled(paths.map(fetchJson)),Promise.resolve(WORLD_SVG||'').then(async cached=>cached||await fetchText('assets/world-map.svg')).then(v=>({status:'fulfilled',value:v})).catch(reason=>({status:'rejected',reason}))]);[KEV,NVD,EPSS,RW,RWHIST,MYCERT,COUNTRY_META,PULSE_WEB]=res.map(x=>x.status==='fulfilled'?x.value:null);if(mapRes.status==='fulfilled')WORLD_SVG=mapRes.value;initCountryAlias();NVD_BY_ID=sourceReady(NVD)?new Map((NVD.vulnerabilities||[]).map(v=>[v.id,v])):new Map();EPSS_BY_ID=sourceReady(EPSS)?new Map((EPSS.vulnerabilities||[]).map(v=>[v.id,v])):new Map();UNIFIED=buildUnified();if(!RW_SEEN_RECENT_IDS&&sourceReady(RW))RW_SEEN_RECENT_IDS=new Set((RW.victims||[]).map(v=>String(v.id||'')).filter(Boolean));renderHeader();renderPosture();renderTopThree();renderKevTrend();renderRiskScatter('riskScatter');renderRiskScatter('riskScatterFull');renderRansomware();renderOverviewAsean();renderOverviewFeed();renderThreadHubOverview();renderStandaloneThreatMap();renderThreatActors();renderFeedStatusView();renderPulse();renderRegional();renderSeverityAndEpss();renderVulnerabilityCommand();renderVendors();populateVulnWorkbench();renderTable();renderUnifiedFeed();renderBriefing();renderSources()}

