  const victims=ransomwareBaseVictims();
  for(const g of rwGroupRows(victims).slice(0,80)){
    const claims=victims.filter(v=>String(v.group||'').toLowerCase()===String(g.name||'').toLowerCase()).sort((a,b)=>dateMs(b.discovered)-dateMs(a.discovered));
    const c24=claims.filter(v=>withinDays(v.discovered,1)).length,c7=claims.filter(v=>withinDays(v.discovered,7)).length,c30=claims.filter(v=>withinDays(v.discovered,30)).length,latest=claims[0];
    if(!claims.length)continue;
    const recentRatio=c30?Math.min(1,c7/Math.max(c30,1)):0,score=Math.min(100,Math.round(35+Math.min(30,c30*2)+Math.min(20,c7*3)+Math.min(15,recentRatio*15)));
    const age=latest?.discovered?Math.max(0,(Date.now()-dateMs(latest.discovered))/86400000):999,mom=pulseMomentum(age,c24);
    const prof=groupProfile(g.name),primary=trustedRansomUrl(prof?.profileUrl||latest?.sourceUrl||ransomwareSourceUrl());
    topics.push({id:pulseTopicId('rw',g.name),title:`${g.name} ransomware`,category:'ransomware',score,momentum:mom,signals:claims.length,recent:c30,latest:latest?.discovered||'',summary:`${fmt(c30)} retained victim claims in 30 days · ${fmt(c7)} in 7 days`,primaryUrl:primary,sourceLabel:'Ransomware.live / source record',entity:g.name,evidence:claims.slice(0,8).map(v=>({label:`${v.victim||'Victim'} · ${countryInfo(v.country)?.name||v.country||'Unknown'}`,url:trustedRansomUrl(v.sourceUrl),time:v.discovered}))});
  }
  // CISA KEV vulnerabilities are one topic per CVE, correlated with NVD and EPSS.
  for(const v of UNIFIED.slice(0,250)){
    const age=ageDays(v.dateAdded),base=v.priority?.score||ctiPriority(v).score,eps=safeNum(v.epss?.epss),score=Math.min(100,Math.round(base+(eps>=.5?5:0))),mom=pulseMomentum(age,v.ransomware?5:0);
    topics.push({id:pulseTopicId('cve',v.id),title:v.vulnerabilityName||v.id,subtitle:v.id,category:'vulnerability',score,momentum:mom,signals:3+(v.ransomware?1:0),recent:age<=30?1:0,latest:v.dateAdded||v.nvd?.lastModified||'',summary:`${v.id} · CVSS ${v.nvd?.cvss?.score??'—'} · EPSS ${v.epss?`${(eps*100).toFixed(1)}%`:'—'}${v.ransomware?' · known ransomware use':''}`,primaryUrl:cisaCveUrl(v.id),sourceLabel:'CISA KEV',entity:v.id,evidence:[{label:'CISA KEV',url:cisaCveUrl(v.id),time:v.dateAdded},{label:'NVD vulnerability record',url:nvdUrl(v.id),time:v.nvd?.lastModified},{label:'FIRST EPSS',url:epssUrl(v.id),time:v.epss?.date}].filter(x=>x.url)});
  }
  // MyCERT advisories add a national-authority advisory stream when present.
  for(const a of (MYCERT?.advisories||[]).slice(0,120)){
    const title=a.title||'MyCERT advisory',when=a.date||a.published||a.collectedAt||'',age=when?Math.max(0,(Date.now()-dateMs(when))/86400000):999,text=`${title} ${a.description||a.summary||''}`.toLowerCase();
    const critical=/ransomware|zero.day|actively exploited|critical|breach|malware/.test(text),score=Math.min(100,Math.round((critical?72:55)+(age<=7?15:age<=30?8:0))),mom=pulseMomentum(age,critical&&age<=3?5:0),url=safeMycertUrl(a.url||a.link||MYCERT?.meta?.sourceUrl||'https://mycert.org.my/portal/index');
    topics.push({id:pulseTopicId('adv',title),title,category:'advisory',score,momentum:mom,signals:1,recent:age<=30?1:0,latest:when,summary:a.description||a.summary||'National cyber security advisory',primaryUrl:url,sourceLabel:'MyCERT',entity:title,evidence:[{label:'MyCERT advisory',url,time:when}]});
  }
