function pulseVisibleTopics(){let x=PULSE_TOPICS.slice();if(PULSE_FILTER!=='all')x=x.filter(t=>t.category===PULSE_FILTER);if(PULSE_QUERY)x=x.filter(t=>`${t.title} ${t.subtitle||''} ${t.summary||''}`.toLowerCase().includes(PULSE_QUERY.toLowerCase()));if(PULSE_VIEW==='emerging')x=x.filter(t=>t.emerging||t.momentum.weight>=2).sort((a,b)=>b.momentum.weight-a.momentum.weight||dateMs(b.latest)-dateMs(a.latest)||b.score-a.score);if(PULSE_VIEW==='verified')x=x.filter(t=>t.verified||t.category==='vulnerability'||t.category==='advisory'||(t.evidence||[]).some(e=>e.url&&e.url!=='#'));return x}
function pulseCatLabel(c){return({ransomware:'RANSOMWARE',vulnerability:'VULNERABILITY',advisory:'ADVISORY',malware:'MALWARE',breach:'DATA BREACH','threat-actor':'THREAT ACTOR',phishing:'PHISHING',cloud:'CLOUD'})[c]||String(c||'SIGNAL').toUpperCase()}
function pulseInvestigateAction(t){return t.category==='ransomware'?`data-pulse-investigate="${esc(t.id)}"`:t.category==='vulnerability'?`data-pulse-investigate="${esc(t.id)}"`:`data-pulse-investigate="${esc(t.id)}"`}
