function exportPulseCsv(){const rows=pulseVisibleTopics(),cols=['rank','topic','category','score','momentum','signals','latest','source'];const q=v=>`"${String(v??'').replace(/"/g,'""')}"`;const csv=[cols.join(','),...rows.map((t,i)=>[i+1,t.title,pulseCatLabel(t.category),t.score,t.momentum.label,t.signals,t.latest,t.primaryUrl].map(q).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`threadhub-pulse-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}
